// The schema of the audit store on PostgreSQL: numbered and append-only, kept apart
// from SQLite's, with the version in the store. Migrations run under an advisory lock,
// so Replicas starting together wait for each other and each applies once.
//
// The same logical schema as SQLite: integer millisecond timestamps, JSON held as text,
// bodies as binary. Every integer is BIGINT, as wide as SQLite's. Ids can be given
// explicitly, so a copy from SQLite keeps them (GENERATED BY DEFAULT).
import type pg from 'pg';
import { refuseNewerStore } from './store-version.js';

export const MIGRATIONS: readonly string[] = [
  // v1: everything SQLite had at its v17.
  `CREATE TABLE audit_entries (
     id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
     created_at BIGINT NOT NULL,
     operator_id TEXT NOT NULL,
     operator_name TEXT NOT NULL,
     operator_role TEXT,
     approver_id TEXT,
     approver_name TEXT,
     broker_user TEXT NOT NULL,
     profile TEXT NOT NULL,
     vhost TEXT NOT NULL,
     queue TEXT NOT NULL,
     message_id TEXT,
     action TEXT NOT NULL,
     reason TEXT,
     destination_exchange TEXT,
     destination_routing_key TEXT,
     destination_queue TEXT,
     outcome TEXT NOT NULL,
     outcome_reason TEXT,
     checkout_id TEXT,
     message_properties TEXT,
     message_headers TEXT,
     body_bytes BIGINT,
     body_expired_at BIGINT,
     replay_id TEXT,
     restore_of BIGINT REFERENCES audit_entries (id),
     filter TEXT,
     message_count BIGINT,
     rate DOUBLE PRECISION,
     rule TEXT,
     rule_pass_id TEXT,
     canary BIGINT NOT NULL DEFAULT 0,
     canary_outcome TEXT
   );
   CREATE TABLE audit_message_bodies (
     entry_id BIGINT PRIMARY KEY REFERENCES audit_entries (id),
     body BYTEA NOT NULL
   );
   CREATE INDEX audit_entries_created_at ON audit_entries (created_at);
   CREATE INDEX audit_entries_queue ON audit_entries (vhost, queue);
   CREATE INDEX audit_entries_destination_queue ON audit_entries (destination_queue);
   CREATE INDEX audit_entries_message_id ON audit_entries (message_id);
   CREATE INDEX audit_entries_checkout_id ON audit_entries (checkout_id);
   CREATE INDEX audit_entries_replay_id ON audit_entries (replay_id);
   CREATE INDEX audit_entries_restore_of ON audit_entries (restore_of);
   CREATE INDEX audit_entries_stored_bodies ON audit_entries (created_at, id)
     WHERE body_bytes IS NOT NULL AND body_expired_at IS NULL;
   CREATE INDEX audit_entries_rule ON audit_entries (rule);
   CREATE INDEX audit_entries_profile_queue_time ON audit_entries (profile, vhost, queue, created_at);

   CREATE TABLE replay_rule_state (
     rule_key TEXT PRIMARY KEY,
     paused BIGINT NOT NULL,
     paused_reason TEXT,
     paused_by TEXT,
     paused_at BIGINT
   );
   CREATE TABLE replay_rule_passes (
     seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
     id TEXT NOT NULL UNIQUE,
     rule_key TEXT NOT NULL,
     at BIGINT NOT NULL,
     status TEXT NOT NULL,
     reason TEXT,
     held BIGINT,
     replayed BIGINT,
     moved BIGINT,
     used_up BIGINT,
     not_due BIGINT,
     no_match BIGINT,
     failed BIGINT,
     cannot_replay BIGINT
   );
   CREATE INDEX replay_rule_passes_rule ON replay_rule_passes (rule_key, at);
   CREATE TABLE replay_rule_first_seen (
     rule_key TEXT NOT NULL,
     message_id TEXT NOT NULL,
     first_seen_at BIGINT NOT NULL,
     PRIMARY KEY (rule_key, message_id)
   );
   CREATE INDEX replay_rule_first_seen_at ON replay_rule_first_seen (rule_key, first_seen_at);
   CREATE TABLE replay_rule_died_again (
     rule_key TEXT NOT NULL,
     audit_entry_id BIGINT NOT NULL,
     seen_at BIGINT NOT NULL,
     PRIMARY KEY (rule_key, audit_entry_id)
   );

   CREATE TABLE notifications (
     id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
     at BIGINT NOT NULL,
     alert_id TEXT NOT NULL,
     destination TEXT NOT NULL,
     destination_type TEXT NOT NULL,
     status TEXT NOT NULL,
     test BIGINT NOT NULL,
     rule TEXT NOT NULL,
     replay_rule TEXT,
     profile TEXT,
     vhost TEXT,
     queue TEXT,
     outcome TEXT NOT NULL,
     http_status BIGINT,
     error TEXT,
     attempts BIGINT NOT NULL
   );
   CREATE INDEX notifications_at ON notifications (at);

   CREATE TABLE history_samples (
     profile TEXT NOT NULL,
     vhost TEXT NOT NULL,
     queue TEXT NOT NULL,
     at BIGINT NOT NULL,
     depth BIGINT NOT NULL,
     estimated_arrivals BIGINT,
     PRIMARY KEY (profile, vhost, queue, at)
   );
   CREATE INDEX history_samples_at ON history_samples (at);
   CREATE TABLE sampling_runs (
     profile TEXT NOT NULL,
     at BIGINT NOT NULL,
     ok BIGINT NOT NULL,
     error_code TEXT,
     interval_ms BIGINT,
     PRIMARY KEY (profile, at)
   );
   CREATE INDEX sampling_runs_at ON sampling_runs (at);

   CREATE TABLE alerts (
     profile TEXT NOT NULL,
     rule TEXT NOT NULL,
     vhost TEXT NOT NULL,
     queue TEXT NOT NULL,
     replay_rule TEXT NOT NULL,
     alert_id TEXT NOT NULL,
     status TEXT NOT NULL,
     condition TEXT NOT NULL,
     value DOUBLE PRECISION,
     threshold DOUBLE PRECISION,
     since BIGINT NOT NULL,
     last_notified_at BIGINT,
     false_since BIGINT,
     reason TEXT,
     PRIMARY KEY (profile, rule, vhost, queue, replay_rule)
   );
   CREATE TABLE alert_queue_arrivals (
     profile TEXT NOT NULL,
     vhost TEXT NOT NULL,
     queue TEXT NOT NULL,
     unsettled BIGINT NOT NULL,
     recent TEXT NOT NULL,
     PRIMARY KEY (profile, vhost, queue)
   );`,
  // v2: sessions and sign-ins in progress, shared by Replicas. PostgreSQL only: on SQLite they stay in memory.
  `CREATE TABLE sessions (
     id TEXT PRIMARY KEY,
     operator TEXT NOT NULL,
     tokens TEXT NOT NULL,
     expires_at BIGINT NOT NULL
   );
   CREATE INDEX sessions_expires_at ON sessions (expires_at);
   CREATE TABLE sign_ins (
     id TEXT PRIMARY KEY,
     sealed TEXT NOT NULL,
     expires_at BIGINT NOT NULL
   );
   CREATE INDEX sign_ins_expires_at ON sign_ins (expires_at);`,
  // v3: who is the Background Leader. One row at most; its term only goes up.
  `CREATE TABLE leader_lease (
     id INTEGER PRIMARY KEY CHECK (id = 1),
     holder TEXT,
     term BIGINT NOT NULL,
     expires_at BIGINT NOT NULL
   );`,
  // v4: Replicas' leases and Live Checkout records. PostgreSQL only: on SQLite there is one Replica.
  `CREATE TABLE replicas (
     id TEXT PRIMARY KEY,
     forwarding_address TEXT NOT NULL,
     lease_expires_at BIGINT NOT NULL
   );
   CREATE TABLE live_checkouts (
     id TEXT PRIMARY KEY,
     owner_replica TEXT NOT NULL,
     operator_id TEXT NOT NULL,
     operator_name TEXT NOT NULL,
     profile TEXT NOT NULL,
     vhost TEXT NOT NULL,
     queue TEXT NOT NULL,
     status TEXT NOT NULL,
     approval TEXT
   );
   CREATE INDEX live_checkouts_owner_replica ON live_checkouts (owner_replica);
   CREATE INDEX live_checkouts_operator_id ON live_checkouts (operator_id);`,
];

/** Any number, the same on every Replica: advisory locks are per database, and this is the only one Volverán takes here. */
const MIGRATION_LOCK = 7_203_940_099;

/**
 * Brings the store up to `migrations`, or refuses it when it is newer than they are.
 * The lock belongs to the session, so the connection is closed afterwards rather than
 * returned to the pool, which also lets go of the lock if anything failed.
 */
export async function migrate(pool: pg.Pool, migrations: readonly string[] = MIGRATIONS): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query('SELECT pg_advisory_lock($1)', [MIGRATION_LOCK]);
    await client.query('CREATE TABLE IF NOT EXISTS audit_store_version (version INTEGER NOT NULL)');
    const { rows } = await client.query<{ version: number }>('SELECT version FROM audit_store_version');
    if (rows.length === 0) await client.query('INSERT INTO audit_store_version (version) VALUES (0)');
    const version = rows[0]?.version ?? 0;
    refuseNewerStore(version, migrations.length);
    for (let v = version; v < migrations.length; v++) {
      await client.query('BEGIN');
      try {
        await client.query(migrations[v]!);
        await client.query('UPDATE audit_store_version SET version = $1', [v + 1]);
        await client.query('COMMIT');
      } catch (err) {
        await client.query('ROLLBACK');
        throw err;
      }
    }
  } finally {
    client.release(true);
  }
}
